-- Fills reliability_rating/pros/cons on the 8 engines Step 2's automated content
-- migration (20261011205548) left undecided -- CBZB@77, DFFA@110, DADA@110, CHZB@70,
-- CRBC@110, DFGA@110, CHHA@169, DFHA@140. Generated by
-- scripts/fill/write-8-engine-merge-migration.mjs from hand-curated, Martin-approved
-- content (see conversation) -- NOT a mechanical pass-through of old-engine rows like
-- the other 25 engines got. Each item kept recurred (same meaning) across >= 2 of the
-- engine's contributing old-vehicle variants; every car-specific category (towing,
-- body/segment remarks, consumption figures, drivetrain differences, trim names) and
-- every gearbox/drivetrain item (CLAUDE.md rule 9) was dropped regardless of how often
-- it recurred. Every numeric/hardware claim (torque_nm, cylinders, timing_type) was
-- cross-checked against the live catalog_engines row before being kept (CLAUDE.md
-- rule 10) -- confirmed again live immediately before writing this file, not just at
-- review time. Reliability is the mode across each engine's contributing variants'
-- mapped 1-5 values, ties resolved to the lower rating.
--
-- COALESCE, so an already-non-NULL column is never overwritten. Review-only: NOT run
-- by this session. Run once, in a fresh SQL editor tab.

BEGIN;

-- Precondition: all 8 engines currently NULL on reliability_rating/pros/cons (confirmed
-- live immediately before writing this file).
DO $$
DECLARE
  non_null_n integer;
BEGIN
  SELECT count(*) INTO non_null_n FROM catalog_engines
  WHERE id IN ('a0e64f01-c8b1-4e74-8fd4-f67421a41417', 'a7269415-4eae-4d33-9c37-2e4bbd6b8b0a', 'eb01556d-9347-4072-bea1-2f0186a05012', '0ca7d37a-1b5d-469a-949f-0d000e5a4ae9', '5cca43f2-9499-47df-83e4-e5c9af808f38', '11959a05-1db6-4740-aa98-6f98fd995ca8', '4a84b959-e99a-4d00-a3b2-e2272acc53d5', '7486fdd1-b0cd-4f97-83b6-f86bfd178864')
    AND (reliability_rating IS NOT NULL OR pros IS NOT NULL OR cons IS NOT NULL);
  IF non_null_n <> 0 THEN
    RAISE EXCEPTION 'Expected 0 of the 8 targeted engines to already have content set, found % -- live state has drifted, aborting.', non_null_n;
  END IF;
END $$;

-- CBZB@77
UPDATE catalog_engines SET
  reliability_rating = COALESCE(reliability_rating, 2),
  pros = COALESCE(pros, ARRAY['Much livelier than the naturally aspirated version — turbo transforms the car']::text[]),
  cons = COALESCE(cons, ARRAY['Timing chain is a known, expensive failure', 'Turbo adds repair complexity to a budget car']::text[])
WHERE id = 'a0e64f01-c8b1-4e74-8fd4-f67421a41417';

