WHERE id = '7486fdd1-b0cd-4f97-83b6-f86bfd178864';

-- Postcondition: all 8 engines now have reliability_rating/pros/cons set.
DO $$
DECLARE
  filled_n integer;
BEGIN
  SELECT count(*) INTO filled_n FROM catalog_engines
  WHERE id IN ('a0e64f01-c8b1-4e74-8fd4-f67421a41417', 'a7269415-4eae-4d33-9c37-2e4bbd6b8b0a', 'eb01556d-9347-4072-bea1-2f0186a05012', '0ca7d37a-1b5d-469a-949f-0d000e5a4ae9', '5cca43f2-9499-47df-83e4-e5c9af808f38', '11959a05-1db6-4740-aa98-6f98fd995ca8', '4a84b959-e99a-4d00-a3b2-e2272acc53d5', '7486fdd1-b0cd-4f97-83b6-f86bfd178864')
    AND reliability_rating IS NOT NULL AND pros IS NOT NULL AND cons IS NOT NULL;
  IF filled_n <> 8 THEN
    RAISE EXCEPTION 'Expected all 8 engines filled, found %.', filled_n;
  END IF;
END $$;

COMMIT;
